using Microsoft.CodeAnalysis; using Microsoft.CodeAnalysis.CSharp; using Microsoft.CodeAnalysis.CSharp.Syntax;
namespace QualityReporter.CSharp.Metrics;
public sealed class CodeMetricsAnalyzer { public (CodeMetric,List<FunctionMetric>) Analyze(string file) { var text=File.ReadAllText(file);var tree=CSharpSyntaxTree.ParseText(text);var root=tree.GetRoot();var funcs=new List<FunctionMetric>();foreach(var n in root.DescendantNodes().Where(n=>n is BaseMethodDeclarationSyntax or LocalFunctionStatementSyntax)){var span=tree.GetLineSpan(n.Span);var name=n switch {MethodDeclarationSyntax x=>x.Identifier.Text,ConstructorDeclarationSyntax x=>x.Identifier.Text,LocalFunctionStatementSyntax x=>x.Identifier.Text,_=>n.Kind().ToString()};funcs.Add(new(name,n is LocalFunctionStatementSyntax?"local-function":"method",span.StartLinePosition.Line+1,span.EndLinePosition.Line+1,Complexity(n)));}var complexity=Math.Max(1,root.DescendantNodes().OfType<BaseMethodDeclarationSyntax>().Sum(Complexity));return(new(){Loc=text.Split('\n').Count(x=>!string.IsNullOrWhiteSpace(x)),Complexity=complexity},funcs); }
 static int Complexity(SyntaxNode n)=>1+n.DescendantNodes().Count(x=>x is IfStatementSyntax or ForStatementSyntax or ForEachStatementSyntax or WhileStatementSyntax or DoStatementSyntax or CatchClauseSyntax or ConditionalExpressionSyntax or CaseSwitchLabelSyntax || x is BinaryExpressionSyntax b&&(b.IsKind(SyntaxKind.LogicalAndExpression)||b.IsKind(SyntaxKind.LogicalOrExpression)));
}
public sealed record AnalyzerIssue(string RuleId,string Severity,string File,int Line);
public static class AnalyzerResultParser { public static List<AnalyzerIssue> Parse(string path) { if(!File.Exists(path))return [];var rx=new System.Text.RegularExpressions.Regex(@"^(.*)\((\d+),\d+\):\s+(error|warning|info)\s+([A-Za-z]+\d+)",System.Text.RegularExpressions.RegexOptions.Multiline|System.Text.RegularExpressions.RegexOptions.IgnoreCase);return rx.Matches(File.ReadAllText(path)).Select(m=>new AnalyzerIssue(m.Groups[4].Value,m.Groups[3].Value.ToLowerInvariant(),m.Groups[1].Value.Replace('\\','/'),int.Parse(m.Groups[2].Value))).ToList(); } }
